-- Blog seed: the five articles that shipped as static data in
-- apps/marketing/src/config/blog.ts (commit e4fe7dd), moved into the CMS.
--
-- Generated by scripts/blog/generate-seed.mts — slugs, titles, excerpts, body
-- text, FAQs, tags, hero images (still served from apps/marketing/public/blog)
-- and captions are carried over verbatim. Block → TipTap mapping:
-- p → paragraph, h2 → heading(2), ul → bulletList, cta → cta node.
--
-- REPEATABLE: categories upsert on their unique slug, and each post inserts
-- only if no row (live or soft-deleted) already holds its slug, so re-running
-- never duplicates an article or resurrects one an editor deleted.
--
-- Dates: the static posts carried no publication date ("omitted until the team
-- sets one"), and none was ever live — production /blog/ returned 404 when this
-- was written. `now()` at apply time is therefore their true first-publication
-- moment, not a fabricated one.

insert into public.blog_categories (name, slug, sort_order) values
  ('Pet Social Life', 'pet-social-life', 0),
  ('Pet Matching & Playdates', 'pet-matching-playdates', 1),
  ('Pet Profiles & Trust', 'pet-profiles-trust', 2),
  ('Local Pet Life & Activities', 'local-pet-life-activities', 3)
on conflict (slug) do nothing;

insert into public.blog_posts (
  slug, title, excerpt, content, faq, category_id, tags, author_name,
  featured_image, featured_image_alt, featured_image_caption, status, published_at
)
select
  'pet-social-networks-india',
  'How Pet Social Networks Are Changing the Way Pet Parents Find Friends in India',
  'Pet parents rely on WhatsApp groups, Instagram and word of mouth to find pet friends. A dedicated pet social network can make that simpler.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Having a pet is not only about feeding, walking, and caring for them. Pets also need companionship, play, and opportunities to interact with other pets."}]},{"type":"paragraph","content":[{"type":"text","text":"But finding the right pet friends nearby is not always easy. Pet parents often depend on WhatsApp groups, Instagram pages, local contacts, or word of mouth to discover other pets. This is where a pet social network can make finding and connecting with other pet parents simpler."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why Pet Parents Need a Better Way to Connect"}]},{"type":"paragraph","content":[{"type":"text","text":"Imagine having a friendly dog that loves playing with other dogs, but not knowing which pets nearby have a similar personality."}]},{"type":"paragraph","content":[{"type":"text","text":"You may search for a dog walking group in Chennai, ask friends about a playdate, or look through local social media communities. These options can help, but the information is often scattered."}]},{"type":"paragraph","content":[{"type":"text","text":"A dedicated pet networking app brings pet profiles and pet parents together in one place. Instead of searching through multiple groups, pet parents can discover pets based on location, interests, and compatibility."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"From Online Profiles to Real Playdates"}]},{"type":"paragraph","content":[{"type":"text","text":"A pet profile can tell you more than just a pet''s name and breed. It can show personality, interests, and other useful details that help pet parents understand whether two pets could get along."}]},{"type":"paragraph","content":[{"type":"text","text":"For example, someone looking for a dog playdate in Chennai can discover nearby pets and connect with their parents before planning a meetup."}]},{"type":"paragraph","content":[{"type":"text","text":"The same idea can work for younger pets. A puppy play date app in Tamil Nadu can help puppy parents discover other local puppies and potentially create opportunities for safe socialisation and play."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Building a Local Pet Community"}]},{"type":"paragraph","content":[{"type":"text","text":"A strong pet community is not limited to individual playdates."}]},{"type":"paragraph","content":[{"type":"text","text":"Pet parents may want to discover local activities, meet other owners, share experiences, or find pet events in Tamil Nadu. A dedicated platform can bring these conversations and connections closer to the people who actually live nearby."}]},{"type":"paragraph","content":[{"type":"text","text":"While some people may prefer a traditional pet community forum in India, others may want a more interactive experience built around pet profiles, discovery, matching, and direct conversations."}]},{"type":"paragraph","content":[{"type":"text","text":"The goal is simple: make it easier for pets and their parents to find their community."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"More Than Just a Social App"}]},{"type":"paragraph","content":[{"type":"text","text":"A useful pet platform can eventually bring several aspects of pet life together."}]},{"type":"paragraph","content":[{"type":"text","text":"From discovering a dog walking group in Chennai to finding local pet activities, keeping important information organised, or connecting with nearby pet parents, digital tools can make everyday pet ownership more connected."}]},{"type":"paragraph","content":[{"type":"text","text":"Features such as a pet vaccination tracker in Tamil Nadu could also help pet parents keep important vaccination information organised, while social features can help them build meaningful connections."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Finding the Right Pet App for Your Needs"}]},{"type":"paragraph","content":[{"type":"text","text":"There is no single best pet app in India for every pet parent. The right platform depends on what you want to do."}]},{"type":"paragraph","content":[{"type":"text","text":"If your goal is simply to track pet information, a specialised tool may be enough. If you want to discover nearby pets, meet other pet parents, and build local connections, a pet parents social app in India can offer a different kind of experience."}]},{"type":"paragraph","content":[{"type":"text","text":"MeetMyPets is being built around this social side of pet ownership."}]},{"type":"paragraph","content":[{"type":"text","text":"Create a pet profile, discover compatible pets nearby, connect with their parents, and start a conversation before planning your next meetup."}]},{"type":"cta","attrs":{"label":"Explore MeetMyPets","href":"/#ecosystem"}},{"type":"paragraph","content":[{"type":"text","text":"Because your pet''s social life can start with a simple connection."}]}]}'::jsonb,
  '[]'::jsonb,
  (select id from public.blog_categories where slug = 'pet-social-life'),
  array['Pet Social Life', 'Pet Community', 'Pet Networking']::text[],
  'MeetMyPets Team',
  '/blog/pet-social-networks-india.webp',
  'Pet parents and their dogs meeting together at an outdoor park in India',
  'Finding the right pet friends nearby does not have to be left to chance.',
  'published',
  now()
where not exists (
  select 1 from public.blog_posts where slug = 'pet-social-networks-india'
);

insert into public.blog_posts (
  slug, title, excerpt, content, faq, category_id, tags, author_name,
  featured_image, featured_image_alt, featured_image_caption, status, published_at
)
select
  'why-pet-socialisation-matters',
  'Why Socialisation Matters for Your Pet''s Everyday Life',
  'Social experiences shape everyday pet life as much as food and exercise. Here is what pet socialisation really means, and how to approach it.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A pet''s world can become much bigger when they have opportunities to meet, interact, and spend time with other pets. While food, exercise, and healthcare are essential parts of responsible pet ownership, social experiences can also play an important role in everyday pet life."}]},{"type":"paragraph","content":[{"type":"text","text":"For many pet parents, however, finding suitable pets nearby is not always simple."}]},{"type":"paragraph","content":[{"type":"text","text":"You might meet another dog during an evening walk, discover a local pet group, or hear about a meetup through friends. But these connections are often unplanned and scattered across different platforms."}]},{"type":"paragraph","content":[{"type":"text","text":"That is where the idea of a pet social network becomes useful."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What Does Pet Socialisation Mean?"}]},{"type":"paragraph","content":[{"type":"text","text":"Pet socialisation is more than simply putting two animals in the same space. It involves helping pets become comfortable around different animals, people, environments, sounds, and experiences in appropriate and positive ways."}]},{"type":"paragraph","content":[{"type":"text","text":"Every pet is different. Some dogs may immediately enjoy meeting new friends, while others may need more time and space. Cats and other pets can have completely different social preferences."}]},{"type":"paragraph","content":[{"type":"text","text":"Understanding your pet''s personality is therefore an important first step."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Finding Pets With Similar Social Interests"}]},{"type":"paragraph","content":[{"type":"text","text":"Imagine being able to create a profile for your pet that describes their personality, interests, and preferences."}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of simply searching for “dogs near me,” you could look for pets that may have similar interests or social habits."}]},{"type":"paragraph","content":[{"type":"text","text":"A pet parents social app India can make this type of discovery more organised by bringing pet profiles and pet parents into the same community."}]},{"type":"paragraph","content":[{"type":"text","text":"MeetMyPets is designed around this idea: helping pet parents discover other pets, connect with their parents, and explore potential friendships."}]},{"type":"cta","attrs":{"label":"Explore MeetMyPets","href":"/#ecosystem"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"From Digital Connections to Real Experiences"}]},{"type":"paragraph","content":[{"type":"text","text":"A digital connection is only the beginning."}]},{"type":"paragraph","content":[{"type":"text","text":"Once two pet parents have connected and had a conversation, they can decide whether a meetup makes sense for their pets. A short walk, a visit to a suitable pet-friendly space, or a planned play session can turn an online discovery into an offline experience."}]},{"type":"paragraph","content":[{"type":"text","text":"For example, someone searching for a dog playdate Chennai may want more than a list of random profiles. They may want to understand the pet, speak with the owner, and decide whether the two dogs could be comfortable together."}]},{"type":"paragraph","content":[{"type":"text","text":"That human connection matters."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Building a More Connected Pet Community"}]},{"type":"paragraph","content":[{"type":"text","text":"A strong pet community is built through small connections: two dogs meeting at a park, two pet parents sharing experiences, or a group discovering a new pet-friendly activity."}]},{"type":"paragraph","content":[{"type":"text","text":"The goal isn''t to make every pet social with every other pet. It is to make it easier for pet parents to discover possibilities and make informed choices."}]},{"type":"paragraph","content":[{"type":"text","text":"If you want to be part of an early community built around pet connections, you can join the MeetMyPets waitlist."}]},{"type":"cta","attrs":{"label":"Join the MeetMyPets Waitlist","href":"/#waitlist"}},{"type":"paragraph","content":[{"type":"text","text":"Your pet''s social life doesn''t have to begin with a chance encounter. Sometimes, it can begin with finding the right community."}]}]}'::jsonb,
  '[{"q":"Why is socialisation important for pets?","a":"Positive social experiences can help pets become more comfortable with different animals, people, and environments. The approach should always consider the individual pet''s temperament."},{"q":"How can I find other pets for my pet?","a":"Pet parents can explore local groups, community events, walking groups, and pet-focused social platforms where available."},{"q":"Does every pet need to socialise with other pets?","a":"Not necessarily. Pets have different personalities and social preferences. Pet interactions should be appropriate, gradual, and comfortable for the animals involved."}]'::jsonb,
  (select id from public.blog_categories where slug = 'pet-social-life'),
  array['Pet Social Life', 'Socialisation', 'Pet Community']::text[],
  'MeetMyPets Team',
  '/blog/why-pet-socialisation-matters.webp',
  'Pet parents and dogs socialising together at an outdoor pet meetup',
  'A healthy pet social life starts with positive connections.',
  'published',
  now()
where not exists (
  select 1 from public.blog_posts where slug = 'why-pet-socialisation-matters'
);

insert into public.blog_posts (
  slug, title, excerpt, content, faq, category_id, tags, author_name,
  featured_image, featured_image_alt, featured_image_caption, status, published_at
)
select
  'find-the-right-playmate-for-your-pet',
  'How to Find the Right Playmate for Your Pet',
  'Finding another pet is easy. Finding the right one is harder. Age, energy, size and personality all shape whether a meetup works.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Finding another pet is easy. Finding the right pet companion can be much harder."}]},{"type":"paragraph","content":[{"type":"text","text":"A dog may live only a few streets away, but that does not automatically mean the two dogs will enjoy spending time together. Age, size, energy levels, personality, and social preferences can all influence whether a meetup is comfortable and enjoyable."}]},{"type":"paragraph","content":[{"type":"text","text":"This is why pet matching can be useful."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What Makes Two Pets Compatible?"}]},{"type":"paragraph","content":[{"type":"text","text":"Compatibility doesn''t necessarily mean two pets have to be identical."}]},{"type":"paragraph","content":[{"type":"text","text":"One energetic puppy may enjoy another playful puppy. A calm adult dog may prefer a quieter companion. Some pets enjoy running and chasing, while others are happier sitting beside another pet."}]},{"type":"paragraph","content":[{"type":"text","text":"When looking for a playmate, pet parents can consider:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Age and life stage"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Energy level"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Size and activity preferences"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Personality"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Social behaviour"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Favourite activities"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Location"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"These details can help pet parents have better conversations before arranging a meetup."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Moving Beyond Random Pet Meetups"}]},{"type":"paragraph","content":[{"type":"text","text":"Traditional methods of finding pet friends often depend on coincidence."}]},{"type":"paragraph","content":[{"type":"text","text":"You may find a dog walking group Chennai, meet another pet at the park, or ask people in your neighbourhood. These can be useful, but they don''t always make it easy to understand whether another pet is a good potential match."}]},{"type":"paragraph","content":[{"type":"text","text":"A pet matching app can create a more structured way to discover pets based on information in their profiles."}]},{"type":"paragraph","content":[{"type":"text","text":"MeetMyPets brings this concept together by allowing pet parents to create profiles, discover other pets, send match requests, and connect before planning a meetup."}]},{"type":"cta","attrs":{"label":"Discover MeetMyPets","href":"/#ecosystem"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A Playdate Starts Before the Meetup"}]},{"type":"paragraph","content":[{"type":"text","text":"The first conversation between pet parents can be just as important as the meetup itself."}]},{"type":"paragraph","content":[{"type":"text","text":"Before meeting, owners can discuss where the meetup will happen, how long it will last, and what their pets are comfortable with."}]},{"type":"paragraph","content":[{"type":"text","text":"For puppies, this can be particularly useful. Someone searching for a puppy play date app Tamil Nadu may be looking for opportunities for their puppy to meet other young pets in an appropriate setting."}]},{"type":"paragraph","content":[{"type":"text","text":"The goal isn''t to force a friendship. It is to create an opportunity for two pets to meet safely and comfortably."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Make the First Meetup Simple"}]},{"type":"paragraph","content":[{"type":"text","text":"A first meetup doesn''t need to be complicated."}]},{"type":"paragraph","content":[{"type":"text","text":"A short walk or a quiet outdoor meeting can be enough. Give the pets space to observe each other, watch their behaviour, and avoid rushing the interaction."}]},{"type":"paragraph","content":[{"type":"text","text":"If the pets are comfortable, future meetups can naturally become longer or more regular."}]},{"type":"paragraph","content":[{"type":"text","text":"MeetMyPets is being built around this simple idea: helping pet parents move from discovery to conversation and, when appropriate, from conversation to real-world meetups."}]},{"type":"cta","attrs":{"label":"Join the MeetMyPets Waitlist","href":"/#waitlist"}},{"type":"paragraph","content":[{"type":"text","text":"The right pet friend may not be the closest pet you can find. It may be the one whose personality and interests fit your pet''s social life."}]}]}'::jsonb,
  '[{"q":"What should I consider before arranging a pet playdate?","a":"Consider personality, age, size, energy level, social behaviour, and any relevant health or vaccination information."},{"q":"Should the first playdate be long?","a":"Not necessarily. A short, controlled introduction can be a better starting point than a long meetup."},{"q":"Can pets with different personalities become friends?","a":"Yes. Pets do not need identical personalities to interact positively. Their individual comfort and behaviour are more important than simply matching characteristics."}]'::jsonb,
  (select id from public.blog_categories where slug = 'pet-matching-playdates'),
  array['Pet Matching & Playdates', 'Playdates', 'Pet Compatibility']::text[],
  'MeetMyPets Team',
  '/blog/find-the-right-playmate-for-your-pet.webp',
  'Two dogs meeting during a pet playdate with their owners',
  'The right playdate starts with finding a compatible companion.',
  'published',
  now()
where not exists (
  select 1 from public.blog_posts where slug = 'find-the-right-playmate-for-your-pet'
);

insert into public.blog_posts (
  slug, title, excerpt, content, faq, category_id, tags, author_name,
  featured_image, featured_image_alt, featured_image_caption, status, published_at
)
select
  'what-to-include-in-a-pet-profile',
  'What Should You Include in a Pet Profile?',
  'A photo and a name rarely tell the whole story. Here is what makes a pet profile genuinely useful to other pet parents.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When people meet a new pet online, a photo and name can be a good starting point. But they rarely tell the whole story."}]},{"type":"paragraph","content":[{"type":"text","text":"Is the pet playful or calm? Do they enjoy meeting other animals? Are they comfortable around children? What activities do they enjoy?"}]},{"type":"paragraph","content":[{"type":"text","text":"A useful pet profile can help answer some of these questions before pet parents decide to connect."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why Pet Profiles Matter"}]},{"type":"paragraph","content":[{"type":"text","text":"A pet profile is more than an online identity. It can give other pet parents useful context about the pet behind the profile."}]},{"type":"paragraph","content":[{"type":"text","text":"Depending on the platform, a profile could include information such as:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pet name"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Age"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Breed or type"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Personality"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interests"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Favourite activities"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Location"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Relevant care information"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Social preferences"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The more useful the information, the easier it can be for pet parents to decide whether they want to start a conversation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Building Trust Between Pet Parents"}]},{"type":"paragraph","content":[{"type":"text","text":"Connecting with a stranger online requires some level of trust."}]},{"type":"paragraph","content":[{"type":"text","text":"This is especially true when the purpose of the connection is eventually to arrange an offline meetup."}]},{"type":"paragraph","content":[{"type":"text","text":"A pet networking app can support this process by giving pet parents more context before they connect. Verification, profile information, and visible trust indicators can help users understand more about the person and pet behind a profile."}]},{"type":"paragraph","content":[{"type":"text","text":"Trust does not mean assuming someone is safe simply because they have a profile. Pet parents should still communicate, ask questions, and make sensible decisions before meeting."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why Verification Can Be Useful"}]},{"type":"paragraph","content":[{"type":"text","text":"Verification can provide an additional layer of information."}]},{"type":"paragraph","content":[{"type":"text","text":"For example, a platform may use verification to confirm certain details about a pet or pet parent. If vaccination information is included, it can also help users understand whether relevant records have been provided."}]},{"type":"paragraph","content":[{"type":"text","text":"This is different from treating a digital badge as a guarantee. Verification should provide useful information, not replace responsible judgement."}]},{"type":"paragraph","content":[{"type":"text","text":"A future-facing pet platform can therefore combine pet profiles, verification, and trust indicators to make online discovery more transparent."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Profiles Can Help With Better Matches"}]},{"type":"paragraph","content":[{"type":"text","text":"Good profiles are also useful for matching."}]},{"type":"paragraph","content":[{"type":"text","text":"If one pet is highly energetic while another prefers quiet walks, their profiles may reveal that difference before the owners arrange a meetup."}]},{"type":"paragraph","content":[{"type":"text","text":"This can save time and make conversations more relevant."}]},{"type":"paragraph","content":[{"type":"text","text":"MeetMyPets is being built to help pet parents create pet profiles, discover compatible pets, and connect before deciding whether to meet."}]},{"type":"cta","attrs":{"label":"Learn About MeetMyPets","href":"/#ecosystem"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start With Information, Then Build the Connection"}]},{"type":"paragraph","content":[{"type":"text","text":"A profile cannot tell you everything about a pet. Behaviour can change depending on the environment and situation."}]},{"type":"paragraph","content":[{"type":"text","text":"But a well-created profile gives pet parents a better starting point."}]},{"type":"paragraph","content":[{"type":"text","text":"As pet communities become more connected, useful profiles and thoughtful conversations can help turn unfamiliar faces into trusted connections."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''d like to follow the development of MeetMyPets and be part of the early community, you can join the waitlist."}]},{"type":"cta","attrs":{"label":"Join the MeetMyPets Waitlist","href":"/#waitlist"}}]}'::jsonb,
  '[{"q":"What information should a pet profile include?","a":"Useful information includes the pet''s age, personality, interests, activities, location, and relevant care or social details."},{"q":"Does a verified profile guarantee a safe meetup?","a":"No. Verification can provide additional information, but pet parents should still communicate and use their own judgment before meeting."},{"q":"Why are pet profiles useful for matching?","a":"Profiles give pet parents information that can help them identify pets with potentially compatible personalities, interests, and activity levels."}]'::jsonb,
  (select id from public.blog_categories where slug = 'pet-profiles-trust'),
  array['Pet Profiles & Trust', 'Pet Profiles', 'Verification']::text[],
  'MeetMyPets Team',
  '/blog/what-to-include-in-a-pet-profile.webp',
  'Pet parent creating an online profile for a dog on a smartphone',
  'A useful pet profile helps pet parents know more before they connect.',
  'published',
  now()
where not exists (
  select 1 from public.blog_posts where slug = 'what-to-include-in-a-pet-profile'
);

insert into public.blog_posts (
  slug, title, excerpt, content, faq, category_id, tags, author_name,
  featured_image, featured_image_alt, featured_image_caption, status, published_at
)
select
  'online-pet-communities-real-world-adventures',
  'From Online Pet Communities to Real-World Adventures',
  'Pet ownership happens locally. Here is how online discovery can turn into walks, meetups and a real neighbourhood pet community.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pet ownership often happens locally."}]},{"type":"paragraph","content":[{"type":"text","text":"Your favourite walking route is nearby. Your pet''s regular park is nearby. The groomer, vet, pet store, and other pet-friendly places you visit are part of your local routine."}]},{"type":"paragraph","content":[{"type":"text","text":"So why should discovering other pets and pet activities happen only through scattered online groups?"}]},{"type":"paragraph","content":[{"type":"text","text":"A connected pet community can help bring online discovery closer to everyday pet life."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Discovering What''s Happening Around You"}]},{"type":"paragraph","content":[{"type":"text","text":"Pet parents are often looking for simple activities."}]},{"type":"paragraph","content":[{"type":"text","text":"It could be a morning walk, a weekend meetup, a puppy play session, or a local pet event. Someone may even be searching for pet events in Tamil Nadu or looking for other owners who regularly walk their dogs in the same area."}]},{"type":"paragraph","content":[{"type":"text","text":"The challenge is discovering these opportunities at the right time and connecting with genuinely interested people."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Turning Pet Connections Into Activities"}]},{"type":"paragraph","content":[{"type":"text","text":"A social platform can make the first step easier."}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of simply reading a post about an event, pet parents could discover other pets, connect with their owners, and potentially attend an activity together."}]},{"type":"paragraph","content":[{"type":"text","text":"For example, two pet parents who discover that their dogs enjoy similar outdoor activities might decide to meet for a walk."}]},{"type":"paragraph","content":[{"type":"text","text":"This creates a connection between the digital and physical sides of pet life."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Local Communities Can Start Small"}]},{"type":"paragraph","content":[{"type":"text","text":"A local pet community doesn''t need hundreds of members to be useful."}]},{"type":"paragraph","content":[{"type":"text","text":"It could begin with a few pet parents in one neighbourhood who want to walk together."}]},{"type":"paragraph","content":[{"type":"text","text":"Over time, those connections can grow into regular meetups, walking groups, playdates, or community activities."}]},{"type":"paragraph","content":[{"type":"text","text":"This is where a dog walking group Chennai, for example, can become more than a group chat. With the right connections, it can become a regular part of the participating pets'' routines."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"More Than Just Socialising"}]},{"type":"paragraph","content":[{"type":"text","text":"Local pet communities can also help people discover useful experiences."}]},{"type":"paragraph","content":[{"type":"text","text":"Pet parents can exchange recommendations, discover pet-friendly locations, learn about upcoming activities, and meet people who understand the everyday realities of living with pets."}]},{"type":"paragraph","content":[{"type":"text","text":"A pet social network can therefore become a starting point for discovering the wider pet ecosystem around you."}]},{"type":"paragraph","content":[{"type":"text","text":"MeetMyPets is being built around connecting pets and their parents so that online discovery can lead to meaningful conversations and, where appropriate, real-world experiences."}]},{"type":"cta","attrs":{"label":"Discover the MeetMyPets Community","href":"/#ecosystem"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Your Local Pet Community Starts With a Connection"}]},{"type":"paragraph","content":[{"type":"text","text":"You don''t need to wait for a large event to meet other pet parents."}]},{"type":"paragraph","content":[{"type":"text","text":"A single conversation can lead to a walk. A walk can lead to a friendship. A few friendships can eventually create a local pet community."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re interested in being part of the early MeetMyPets community, you can join the waitlist and stay connected as the platform develops."}]},{"type":"cta","attrs":{"label":"Join the MeetMyPets Waitlist","href":"/#waitlist"}},{"type":"paragraph","content":[{"type":"text","text":"Because your pet''s world isn''t limited to your home. There is a whole local community waiting to be discovered."}]}]}'::jsonb,
  '[{"q":"What are some local activities pet parents can do together?","a":"Pet parents can organise walks, playdates, outdoor meetups, training activities, and visits to suitable pet-friendly places."},{"q":"How can I find other pet parents near me?","a":"Local pet groups, community events, walking groups, and pet-focused social platforms can help you discover other pet parents."},{"q":"Can online pet communities lead to offline friendships?","a":"Yes. Online platforms can make it easier to discover and communicate with other pet parents. Any offline meetup should be planned thoughtfully with the pets'' comfort and safety in mind."}]'::jsonb,
  (select id from public.blog_categories where slug = 'local-pet-life-activities'),
  array['Local Pet Life & Activities', 'Pet Events', 'Local Community']::text[],
  'MeetMyPets Team',
  '/blog/online-pet-communities-real-world-adventures.webp',
  'Pet parents and dogs enjoying a local outdoor pet meetup',
  'Online connections can become real-world pet experiences.',
  'published',
  now()
where not exists (
